window.kbPageData["views/entry/k-1766c2f7cfaf5f07"] = {"key":"entry/k-1766c2f7cfaf5f07","state":{"route":"entry/k-1766c2f7cfaf5f07"},"node":{"id":"k-1766c2f7cfaf5f07","mode":"k","title":"二十届五中全会（10 月 26 日至 29 日）","type":"事实与事件","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["party"],"主类":["事实与事件"],"出处性质":["时政汇编"],"学科":["政治理论"],"时间索引":["年度事件或数据"],"来源主题":["重要会议讲话"],"资料类别":["时政"]},"eventTags":[{"year":2026,"title":"党的二十届五中全会","slug":"6a94c2ad76dd"}],"directorySummary":"考点四十三 二十届五中全会（10 月 26 日至 29 日）\n全会指出，持之以恒推进全面从严治党，必须坚持马克思列宁主义、毛泽东思想、邓小平理\n论、“三个代表”重要思想、科学发展观，全面贯彻习近平新时代中国特色社会主义思想，深\n入学习贯彻习近平党建思想，围绕实现党的使命任务，落实新时代党的建设总要求…","sources":[{"id":"fcf7e8e678576d45","label":"二十届五中全会（10 月 26 日至 29 日）","topic":"重要会议讲话","category":"时政","text":"考点四十三 二十届五中全会（10 月 26 日至 29 日）\n全会指出，持之以恒推进全面从严治党，必须坚持马克思列宁主义、毛泽东思想、邓小平理\n论、“三个代表”重要思想、科学发展观，全面贯彻习近平新时代中国特色社会主义思想，深\n入学习贯彻习近平党建思想，围绕实现党的使命任务，落实新时代党的建设总要求，以党章为\n根本，坚持党的先锋队性质，坚持党的全面领导和党中央集中统一领导，着眼于提高党的长期\n执政能力、保持党的先进性和纯洁性、保持党同人民群众的血肉联系，坚持严的基调不动摇，\n健全全面从严治党体系，以党的政治建设为统领，全面推进党的各方面建设，充分激发全党积\n极性主动性创造性，不断实现党的自我净化、自我完善、自我革新、自我提高，持续增强党的\n政治领导力、思想引领力、群众组织力、社会号召力，确保党始终成为走在时代前列、人民衷\n心拥护、经得起各种风浪考验、朝气蓬勃的马克思主义执政党，始终成为中国特色社会主义事\n业的坚强领导核心。\n全会强调，持之以恒推进全面从严治党遵循的原则是：坚持服务使命任务，坚持以党的政治建\n设为统领，坚持全面从严，坚持问题导向，坚持守正创新，坚持以上率下，坚持依规治党。\n全会提出，增强党性是全面从严治党的根本性任务。必须推动全体党员、干部坚持党的性质和\n宗旨，增强党的意识、党员意识、先锋队意识，把加强党性修养作为终身课题，在坚定理想信\n念、铸牢对党忠诚、厚植为民情怀、坚持实事求是、纯正道德品质、保持清正廉洁等方面下功\n夫，做到忠诚干净担当，始终保持共产党人政治本色。要强化对党忠诚教育，坚持用党的创新\n理论凝心铸魂，用党的优良传统和中华优秀传统文化涵养党性，在实践中锤炼党性，加强党性\n鉴别。\n全会提出，民主集中制是党的根本组织原则和领导制度，贯彻执行民主集中制是全面从严治党\n的内在要求。必须完善和落实民主集中制各项制度，充分发扬党内民主，有效实行正确的集\n中，更好发挥民主集中制的政治优势、组织优势、制度优势、工作优势。要坚持和加强党中央\n集中统一领导，提高党内民主质量，严格执行领导班子决策议事规则，规范“一把手”履职用\n权。\n全会提出，全面从严治党关键在从严治吏。必须贯彻新时代党的组织路线，严格干部教育培\n养、选拔任用、管理监督，建设一支政治过硬、本领高强、作风优良、纪律严明的高素质干部\n队伍。要坚持正确用人导向，精准科学选人用人，推动干部树立和践行正确政绩观，增强干部\n干事创业本领，提高培养选拔优秀年轻干部质量，加强干部管理监督，全方位培养、引进、用\n好人才。\n全会提出，党的各级组织是全面从严治党的主体。必须体系化推进各层级各领域党组织建设，\n强化党组织政治功能和组织功能，确保贯彻落实党的路线方针政策和党中央决策部署上下协\n同、精准高效。要发挥中央和国家机关党组织表率作用，强化地方党委功能，统筹推进各领域\n基层党组织建设，突出抓好新兴领域党的建设，加强党员队伍建设，完善党的各级组织贯通机\n制。\n全会提出，正风肃纪是全面从严治党的有力举措。必须坚持党性党风党纪一起抓、正风肃纪反\n腐相贯通，深化运用从抓作风入手推进全面从严治党经验，不断改进作风，用严明的纪律管党\n治党，以良好形象凝心聚力。要走好新时代党的群众路线，锲而不舍落实中央八项规定精神，\n推进作风建设常态化长效化，强化从严执纪，综合发挥纪律教育约束、保障激励作用。\n全会提出，一体推进不敢腐不能腐不想腐是全面从严治党的重要方略和反腐败斗争的基本方\n针。必须牢记党除了工人阶级和最广大人民群众的利益没有自己特殊的利益、党同腐败水火不\n容，坚定走好中国特色反腐败之路，加强党中央对反腐败工作的集中统一领导，更加注重标本\n兼治、系统施治，坚持从严惩、精准治、有效防、一体抓，将反腐败斗争进行到底。要保持惩\n治腐败高压态势，加强对权力运行的制约和监督，夯实崇廉拒腐思想根基，增强一体推进不敢\n腐不能腐不想腐综合效能。\n全会提出，加强党内法规制度建设是全面从严治党的长远之策、根本之策。必须坚持把党章作\n为全党的根本行为规范，深化党的建设制度改革，推动依法治国和依规治党有机统一，为持之\n以恒推进全面从严治党提供有力制度保障。要完善党内法规制度体系，增强制度执行力，大力\n破除潜规则。\n全会提出，持之以恒推进全面从严治党，必须进一步完善党和国家监督体系。要做实党委（党\n组）全面监督，完善纪检监察工作双重领导体制，推动党内监督同各方面监督深度融合、高效\n联动，发挥巡视综合监督利剑作用。\n全会强调，持之以恒推进全面从严治党是全党的共同政治责任。必须扭住管党治党责任制“牛\n鼻子”，健全各负其责、统一协调的责任体系，优化责任落实考评机制，对管党治党不力、出\n现严重问题的严肃追责问责。","source":{"doc":"4e539a366dce19555ccf","first":10,"last":12,"page":10,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"party","title":"党的建设与自我革命"}],"units":{"k-1766c2f7cfaf5f07":[]}};
